+bool VM_Version::pre_restore(VM_Features image_features, const char *image_location) {
+  bool image_supports_sve256 = image_features.supports_feature(CPU_SVE256);
+  if (image_supports_sve256 == _cpu_features.supports_feature(CPU_SVE256)) {
+    return true;
+  }
+  if (image_supports_sve256 && !_cpu_features.supports_feature(CPU_SVE256)) {
+    if (Abstract_VM_Version::should_skip_cpu_features_check()) {
+      return true;
+    }
+    ResourceMark rm;
+    VM_Features sve256;
+    sve256.set_feature(CPU_SVE256);
+    VM_Features use = image_features & _cpu_features;
+    log_error(crac)("Image %s has -XX:CPUFeatures=%s with CPU_SVE256=%s, this CPU has CPUFeatures=%s not supporting CPU_SVE256, use -XX:CPUFeatures=%s during snapshot",
+                    image_location, image_features.print_numbers(), sve256.print_numbers(), _cpu_features.print_numbers(), use.print_numbers());
+    return false;
+  }
+  set_maximum_sve_vector_length(16);
+  errno = 0;
+  int got = set_and_get_current_sve_vector_length(16);
+  if (got != 16) {
+    ResourceMark rm;
+    VM_Features sve256;
+    sve256.set_feature(CPU_SVE256);
+    log_error(crac)("Image %s has -XX:CPUFeatures=%s with CPU_SVE256=%s unset, this CPU has CPUFeatures=%s but PR_SVE_SET_VL reports %d: %s",
+                    image_location, image_features.print_numbers(), sve256.print_numbers(), _cpu_features.print_numbers(), got, os::strerror(errno));
+    return false;
+  }
+  return true;
+}

